//! `FeatureSorter` against the real vanilla class on the biome sources of the overworld/nether/end and several flat
//! worlds. Fixture: `tests/fixtures/decoration/decoration.txt`, generated by `tests/oracle/DecorationOracle.java` (see
//! its header). `FEATURES <generator> <step> <placed features in order>` lines are reproduced verbatim.

use crate::decoration_common::{feature_name, fixture, generators};
use mc_game::world::level::levelgen::decoration::sort_features_per_step;

#[test]
fn feature_sorter_matches_vanilla() {
    let text = fixture();
    let all = generators(&text);
    let sorted: Vec<_> = all
        .generators
        .iter()
        .map(|(name, generator)| {
            (
                name.as_str(),
                sort_features_per_step(generator.as_ref(), &all.biomes)
                    .unwrap_or_else(|e| panic!("{name}: {e}")),
            )
        })
        .collect();

    let mut checked = 0;
    for line in text.lines().filter_map(|l| l.strip_prefix("FEATURES ")) {
        let mut parts = line.splitn(3, ' ');
        let (name, step, expected) = (
            parts.next().unwrap(),
            parts.next().unwrap().parse::<usize>().unwrap(),
            parts.next().unwrap_or(""),
        );
        let (_, steps) = sorted.iter().find(|(n, _)| *n == name).unwrap();
        let got: Vec<String> = steps[step].iter().map(feature_name).collect();
        assert_eq!(got.join(","), expected, "{name} step {step}");
        checked += 1;
    }
    // vanilla prints one line per step: the step counts agree too
    for (name, steps) in &sorted {
        assert_eq!(
            text.lines()
                .filter(|l| l.starts_with(&format!("FEATURES {name} ")))
                .count(),
            steps.len(),
            "{name}"
        );
    }
    assert_eq!(checked, 86);
}
